"""ThreadingHTTPServer front end: admin surface plus the proxy surface."""

from __future__ import annotations

import json
import sys
import time
import urllib.parse
import uuid
from http.server import BaseHTTPRequestHandler, ThreadingHTTPServer
from typing import Any, Dict, Optional, Tuple

from .config import GatewayError
from .gateway import Gateway

ADMIN_GET = ("/healthz", "/v1/config", "/v1/quota/usage", "/v1/audit")
ADMIN_POST = ("/v1/config/reload", "/v1/keys", "/v1/quota/policies", "/v1/breaker/reset")


class GatewayHTTPServer(ThreadingHTTPServer):
    daemon_threads = True
    allow_reuse_address = True

    def __init__(self, address: Tuple[str, int], gateway: Gateway, quiet: bool = False) -> None:
        super().__init__(address, GatewayHandler)
        self.gateway = gateway
        self.quiet = quiet


class GatewayHandler(BaseHTTPRequestHandler):
    server_version = "gwd/0.1"
    protocol_version = "HTTP/1.1"

    def do_GET(self) -> None:
        self._dispatch()

    def do_POST(self) -> None:
        self._dispatch()

    def do_PUT(self) -> None:
        self._dispatch()

    def do_PATCH(self) -> None:
        self._dispatch()

    def do_DELETE(self) -> None:
        self._dispatch()

    def log_message(self, fmt: str, *args: Any) -> None:
        if not getattr(self.server, "quiet", False):
            sys.stderr.write("%s %s\n" % (self.address_string(), fmt % args))

    # ------------------------------------------------------------------ plumbing
    def _dispatch(self) -> None:
        gateway: Gateway = self.server.gateway
        now_ms = int(time.time() * 1000)
        length = int(self.headers.get("Content-Length") or 0)
        raw = self.rfile.read(length).decode("utf-8", "replace") if length > 0 else ""
        target, _, query = self.path.partition("?")
        params = urllib.parse.parse_qs(query)
        headers = {k.lower(): v for k, v in self.headers.items()}
        request_id = headers.get("x-request-id") or uuid.uuid4().hex[:16]
        try:
            handled = self._admin(gateway, target, raw, params, request_id)
            if handled:
                return
        except GatewayError as exc:
            self._json(exc.status, {"error": exc.message, "request_id": request_id}, request_id)
            return
        except ValueError as exc:
            self._json(400, {"error": str(exc), "request_id": request_id}, request_id)
            return
        path = target
        if path == "/gw":
            path = "/"
        elif path.startswith("/gw/"):
            path = path[3:]
        tenant = _first(params, "tenant") or headers.get("x-tenant") or ""
        response = gateway.handle(tenant, self.command, path, headers, raw, now_ms)
        self._send(response["status"], response["body"], response["headers"])

    def _admin(self, gateway: Gateway, target: str, raw: str,
               params: Dict[str, Any], request_id: str) -> bool:
        if target in ADMIN_GET and self.command != "GET":
            return False
        if target in ADMIN_POST and self.command != "POST":
            return False
        if target == "/healthz":
            self._json(200, gateway.health(), request_id)
        elif target == "/v1/config":
            self._json(200, gateway.sanitized_config(), request_id)
        elif target == "/v1/config/reload":
            reloaded = gateway.reload_config()
            self._json(200, {"reloaded": reloaded, "revision": gateway.store.revision,
                             "ready": bool(gateway.store.ready),
                             "error": gateway.store.last_error}, request_id)
        elif target == "/v1/keys":
            payload = _json_body(raw)
            extras = {name: payload[name] for name in ("enabled", "expires_at_ms")
                      if name in payload}
            out = gateway.add_key(payload.get("tenant") or "", payload.get("scopes"),
                                  payload.get("key_id"), **extras)
            self._json(201, out, request_id)
        elif target == "/v1/quota/policies":
            self._json(201, gateway.add_policy(_json_body(raw)), request_id)
        elif target == "/v1/quota/usage":
            self._json(200, gateway.usage(_first(params, "tenant") or "",
                                          _int_or_none(_first(params, "since"))), request_id)
        elif target == "/v1/audit":
            tenant = _first(params, "tenant") or ""
            limit = _int_or_none(_first(params, "limit"))
            entries = gateway.audit(tenant, 50 if limit is None else limit)
            self._json(200, {"tenant": tenant, "count": len(entries), "entries": entries}, request_id)
        elif target == "/v1/breaker/reset":
            payload = _json_body(raw, default={})
            self._json(200, {"reset": gateway.breaker_reset(payload.get("upstream"))}, request_id)
        else:
            return False
        return True

    def _json(self, status: int, payload: Any, request_id: str) -> None:
        self._send(status, json.dumps(payload, sort_keys=True), {"X-Request-Id": request_id})

    def _send(self, status: int, text: str, headers: Optional[Dict[str, str]] = None) -> None:
        headers = headers or {}
        payload = (text or "").encode("utf-8")
        self.send_response(int(status))
        has_type = False
        for name, value in headers.items():
            lowered = str(name).lower()
            if lowered in ("content-length", "transfer-encoding", "connection"):
                continue
            if lowered == "content-type":
                has_type = True
            self.send_header(str(name), str(value))
        if not has_type:
            self.send_header("Content-Type", "application/json")
        self.send_header("Content-Length", str(len(payload)))
        self.end_headers()
        if payload:
            self.wfile.write(payload)


def _json_body(raw: str, default: Optional[Dict[str, Any]] = None) -> Dict[str, Any]:
    if not raw.strip():
        if default is not None:
            return default
        raise GatewayError("request body must be a JSON object")
    try:
        payload = json.loads(raw)
    except ValueError as exc:
        raise GatewayError("request body is not valid JSON: %s" % exc)
    if not isinstance(payload, dict):
        raise GatewayError("request body must be a JSON object")
    return payload


def _first(params: Dict[str, Any], key: str) -> Optional[str]:
    values = params.get(key)
    return values[0] if values else None


def _int_or_none(value: Optional[str]) -> Optional[int]:
    if value is None or value == "":
        return None
    try:
        return int(value)
    except ValueError:
        raise GatewayError("query parameter must be an integer: %s" % value)


def create_server(gateway: Gateway, host: str = "127.0.0.1", port: int = 8080,
                  quiet: bool = False) -> GatewayHTTPServer:
    """Build (but do not start) the HTTP server bound to ``host:port``."""
    return GatewayHTTPServer((host, int(port)), gateway, quiet=quiet)

"""Upstream registry: in-process handlers plus a small stdlib HTTP client."""

from __future__ import annotations

import json
import urllib.error
import urllib.request
from typing import Any, Callable, Dict, List, Optional

from .config import sha256_hex


class UpstreamError(Exception):
    """Raised when an upstream cannot be reached or produced no response."""


class Upstream:
    """A callable backend. ``call`` returns ``{"status", "headers", "body"}``."""

    def __init__(self, name: str) -> None:
        self.name = name

    def call(self, request: Dict[str, Any], timeout_ms: int) -> Dict[str, Any]:
        raise NotImplementedError


class InProcessUpstream(Upstream):
    """Wraps a function taking the request dict and returning a response dict."""

    def __init__(self, name: str, fn: Callable[[Dict[str, Any]], Any]) -> None:
        super().__init__(name)
        self.fn = fn

    def call(self, request: Dict[str, Any], timeout_ms: int) -> Dict[str, Any]:
        try:
            result = self.fn(dict(request))
        except UpstreamError:
            raise
        except Exception as exc:  # a handler bug is an upstream failure, not a crash
            raise UpstreamError("%s: %s: %s" % (self.name, type(exc).__name__, exc))
        return normalise(self.name, result)


class HttpUpstream(Upstream):
    """Calls a real HTTP backend with :mod:`urllib` (standard library only)."""

    def __init__(self, name: str, base_url: str) -> None:
        super().__init__(name)
        self.base_url = base_url.rstrip("/")

    def call(self, request: Dict[str, Any], timeout_ms: int) -> Dict[str, Any]:
        url = self.base_url + request["path"]
        body = request.get("body") or ""
        data = body.encode("utf-8") if body else None
        http_request = urllib.request.Request(url, data=data, method=request["method"].upper())
        for name, value in (request.get("headers") or {}).items():
            if name.lower() in ("host", "content-length", "connection"):
                continue
            http_request.add_header(name, str(value))
        timeout = max(0.001, timeout_ms / 1000.0)
        try:
            with urllib.request.urlopen(http_request, timeout=timeout) as response:
                return {"status": int(response.status), "headers": dict(response.headers),
                        "body": response.read().decode("utf-8", "replace")}
        except urllib.error.HTTPError as exc:
            raw = exc.read() if hasattr(exc, "read") else b""
            return {"status": int(exc.code), "headers": dict(exc.headers or {}),
                    "body": raw.decode("utf-8", "replace")}
        except (urllib.error.URLError, OSError, ValueError) as exc:
            raise UpstreamError("%s: %s" % (self.name, exc))


def normalise(name: str, result: Any) -> Dict[str, Any]:
    """Accept a response dict or a ``(status, body)`` tuple."""
    if isinstance(result, tuple) and len(result) == 2:
        result = {"status": result[0], "body": result[1]}
    if not isinstance(result, dict) or "status" not in result:
        raise UpstreamError("%s: handler must return a response dict or (status, body)" % name)
    body = result.get("body", "")
    if not isinstance(body, str):
        body = json.dumps(body, sort_keys=True)
    headers = {str(k): str(v) for k, v in (result.get("headers") or {}).items()}
    return {"status": int(result["status"]), "headers": headers, "body": body}


class UpstreamRegistry:
    def __init__(self) -> None:
        self._items: Dict[str, Upstream] = {}

    def register(self, name: str, target: Any) -> Upstream:
        upstream = target if isinstance(target, Upstream) else InProcessUpstream(name, target)
        self._items[name] = upstream
        return upstream

    def get(self, name: str) -> Upstream:
        upstream = self._items.get(name)
        if upstream is None:
            raise UpstreamError("unknown upstream: %s" % name)
        return upstream

    def call(self, name: str, request: Dict[str, Any], timeout_ms: int) -> Dict[str, Any]:
        return self.get(name).call(request, timeout_ms)

    def names(self) -> List[str]:
        return sorted(self._items)


def echo_upstream(request: Dict[str, Any]) -> Dict[str, Any]:
    """Deterministic test upstream: reports what the gateway actually sent."""
    return {"status": 200, "body": {"method": request.get("method"),
                                    "path": request.get("path"),
                                    "headers": request.get("headers") or {},
                                    "body_sha256": sha256_hex(request.get("body") or "")}}


def default_registry(with_echo: bool = True) -> UpstreamRegistry:
    registry = UpstreamRegistry()
    if with_echo:
        registry.register("echo", echo_upstream)
    return registry


def http_upstream(name: str, base_url: Optional[str] = None) -> HttpUpstream:
    return HttpUpstream(name, base_url or "http://127.0.0.1:9000")

